-- 신·인물의 분류: 신(god), 영웅(hero), 신수(beast: 괴물·영수·환수), 그 밖의 존재(other: 마녀·악마·정령·수호물 등)
alter table public.figures
  add column kind text not null default 'god'
  check (kind in ('god', 'hero', 'beast', 'other'));

update public.figures set kind = 'hero' where slug in ('gilgamesh', 'cuchulainn', 'dangun', 'vainamoinen', 'ilmarinen', 'lemminkainen', 'heracles', 'hanuman', 'kalevipoeg', 'emese', 'weland', 'beowulf', 'thracian-heros', 'eight-deer', 'maui', 'gesar', 'thanh-giong', 'lac-long-quan', 'ungnyeo', 'yuhwa', 'dongmyeong', 'hyeokgeose', 'suro', 'gangnim', 'choeyeong');
update public.figures set kind = 'beast' where slug in ('barong', 'illuyanka', 'medusa', 'turul', 'were-jaguar');
update public.figures set kind = 'other' where slug in ('baba-yaga', 'vanapagan', 'charun', 'louhi', 'nommo', 'moai', 'thotsakan', 'rangda', 'jangseung');

-- 건국 시조와 실존 인물을 영웅으로 소개하고, 치우를 한국 신화로 옮깁니다. (시드는 이미 있는 행을 건너뛰므로 여기서 고칩니다)
update public.figures set pantheon_slug = 'korean', name = '유화', name_en = 'Yuhwa', epithet = '고구려 건국 신화의 어머니 영웅', domains = array['물', '곡식', '어머니']::text[], summary = '물의 신 하백의 딸로, 알을 낳아 주몽을 기른 고구려 건국 신화의 영웅입니다. 고구려에서는 뒤에 ‘부여신’으로 모셨습니다.', description = array['유화는 해모수와 정을 맺은 일로 아버지에게 쫓겨났고, 동부여의 금와왕이 그를 거두었습니다. 햇빛이 몸을 따라 비춘 뒤 큰 알을 낳았고, 그 알에서 주몽이 태어났습니다.', '주몽이 부여를 떠날 때 다섯 가지 곡식의 씨앗을 싸 주었다고 전해 곡식의 신으로도 봅니다. 중국 역사서는 고구려가 나무로 깎은 부인상을 ‘부여신’이라 부르며 섬겼다고 적었습니다.']::text[], sort_order = 9, updated_at = now() where slug = 'yuhwa';
update public.figures set pantheon_slug = 'korean', name = '동명성왕', name_en = 'King Dongmyeong (Jumong)', epithet = '고구려를 세운 건국 영웅', domains = array['건국', '활쏘기']::text[], summary = '알에서 태어나 활을 잘 쏘아 ‘주몽’이라 불렸고, 부여를 떠나 고구려를 세운 건국 영웅입니다.', description = array['주몽은 금와왕의 아들들이 시기해 목숨을 노리자 부여를 떠났습니다. 큰 강에 가로막히자 ‘나는 천제의 아들이자 하백의 외손자’라고 외쳤고, 물고기와 자라가 떠올라 다리를 놓아 주었다고 전합니다.', '414년에 세운 광개토왕릉비는 첫머리에서 시조 추모왕(주몽)을 ‘천제의 아들이자 하백의 딸의 아들’로 기록해, 한국 건국 신화를 전하는 가장 이른 글로 꼽힙니다.']::text[], sort_order = 10, updated_at = now() where slug = 'dongmyeong';
update public.figures set pantheon_slug = 'korean', name = '박혁거세', name_en = 'Bak Hyeokgeose', epithet = '신라를 세운 건국 영웅', domains = array['건국', '빛']::text[], summary = '나정 옆 자줏빛 알에서 태어나 몸에서 빛을 냈다는, 신라를 세운 건국 영웅입니다.', description = array['여섯 마을의 우두머리들이 임금을 모시자고 의논할 때, 나정이라는 우물 옆에서 흰 말이 절하는 곳에 자줏빛 알이 있었고 그 알에서 사내아이가 태어났다고 「삼국유사」는 전합니다.', '예순한 해를 다스린 뒤 하늘로 올라갔다가 이레 뒤 몸이 흩어져 땅에 떨어졌습니다. 사람들이 합쳐 묻으려 하자 큰 뱀이 막아 다섯 곳에 따로 묻었다는 이야기가 경주 오릉의 내력으로 전합니다.']::text[], sort_order = 11, updated_at = now() where slug = 'hyeokgeose';
update public.figures set pantheon_slug = 'korean', name = '수로왕', name_en = 'King Suro', epithet = '가락국을 세운 건국 영웅', domains = array['건국', '하늘']::text[], summary = '구지봉에서 사람들이 노래하며 춤추자 하늘에서 내려온 황금 알에서 태어나 가락국을 세운 건국 영웅입니다.', description = array['「삼국유사」에 실린 「가락국기」에 따르면, 하늘의 소리를 따라 아홉 우두머리와 백성이 ‘거북아 거북아 머리를 내어라’ 하는 노래를 부르자 자줏빛 줄에 매달린 금빛 상자가 내려왔고, 그 안의 황금 알 여섯에서 여섯 가야의 왕이 태어났습니다.', '가장 먼저 나온 수로는 가락국(금관가야)의 왕이 되었고, 바다 건너 아유타국에서 온 허황옥을 왕비로 맞았다고 전합니다.']::text[], sort_order = 12, updated_at = now() where slug = 'suro';
update public.figures set pantheon_slug = 'korean', name = '최영', name_en = 'Choe Yeong', epithet = '왜구를 물리친 고려의 영웅', domains = array['장수', '청렴', '수호']::text[], summary = '왜구와 홍건적을 물리친 고려 말의 명장으로, 억울하게 죽은 뒤 무속에서 장군으로 모셔진 영웅입니다.', description = array['최영(1316~1388)은 왜구와 홍건적을 물리친 고려 말의 명장으로, ‘황금 보기를 돌같이 하라’는 아버지의 말을 지킨 청렴함으로 유명합니다. 위화도 회군 뒤 이성계 세력에게 죽임을 당했습니다.', '억울한 죽음 때문에 무당들은 장군당에 그를 모시고 집안과 마을을 지켜 주기를 빌었습니다. 그의 무덤에는 원한 때문에 풀이 나지 않는다는 전설이 있습니다.']::text[], sort_order = 20, updated_at = now() where slug = 'choeyeong';
update public.figures set pantheon_slug = 'korean', name = '치우', name_en = 'Chiyou', epithet = '황제와 싸운 전쟁의 신', domains = array['전쟁', '무기', '비바람']::text[], summary = '구리 머리에 쇠 이마를 가졌다는 전쟁의 신으로, 옛 기록에서 황제와 탁록에서 싸웠다고 전하며 한국에서는 붉은악마의 상징으로 널리 알려졌습니다.', description = array['「산해경」에 따르면 치우는 무기를 만들어 황제에게 맞섰고, 「사기」는 둘이 탁록의 들판에서 싸웠다고 적었습니다. 후대 기록은 그에게 구리 머리와 쇠 이마를 가진 형제가 여든하나 있었다고 전합니다. 바람의 신 풍백과 비의 신 우사를 불러 큰 비바람을 일으켰지만, 황제가 내려보낸 가뭄의 여신 발이 비를 그치게 해 결국 사로잡혀 죽었다고 합니다.', '패한 뒤에도 전쟁의 신 ‘병주’로 제사를 받았습니다. 20세기에 나온 「환단고기」는 그를 배달국의 임금 ‘치우천왕’으로 그렸는데, 학계는 이 책을 위서로 봅니다. 2002년 월드컵 때 응원단 붉은악마가 그의 얼굴을 상징으로 쓰면서 한국에서 널리 알려졌습니다.']::text[], sort_order = 22, updated_at = now() where slug = 'chiyou';
